import {gzipSync,gunzipSync} from 'node:zlib';
import test from 'node:test';import assert from 'node:assert/strict';
import {activePhysicsTrace,withPhysicsTrace} from '../src/physics/passive-trace.js';
import {prepareSolidPolygon} from '../src/physics/solid-polygon-contact.js';
import {Physics} from '../src/physics/physics.js';
import {createBoardFlow} from '../src/pixi/board-flow.js';
import {measurePinAdjustment} from '../src/dev/pin-adjustment-measurement.js';
import {measureS8WindmillCase} from '../src/dev/s8-windmill-comparison.js';
import {gapCrossings,roadGapDefinitions,withFlowTrace,createFlowTraceCollector} from '../src/dev/s8-flow-trace.js';
import {parseFlowTraceArgs,compareFlowOracle} from '../tools/s8-flow-trace.mjs';
const config=()=>({id:'baseline',label:'変更前・風車の元位置',leftAdmissionGuides:true,hesoMouthWidth:20,launchRailProfile:'legacy',normalPower:.18,moves:[],windmillOffset:{dx:0,dy:0}});
const pins=()=>createBoardFlow({lcd:true}).flow.physics.pins;
function synthetic(operation){const step=Physics.prototype.step,canLaunch=Physics.prototype.canLaunch;Physics.prototype.canLaunch=()=>true;Physics.prototype.step=function(dt,game){this.time+=dt;this.updateGate(game);for(const b of this.balls){this.recordOutcome(b,'out');game.lose(b);}this.balls=[];};try{return operation();}finally{Physics.prototype.step=step;Physics.prototype.canLaunch=canLaunch;}}
test('short real observation OFF/ON retains all JSON/events/replay and ordered substep/motion/contact trace',()=>{
 const options={seconds:2,drain:1,replaySeconds:3,replayFPS:30},plain=measurePinAdjustment(config(),options),events=[];const traced=withFlowTrace(()=>measurePinAdjustment(config(),options),pins(),e=>events.push(e));assert.deepEqual(traced.result,plain);assert.ok(events.some(e=>e.type==='motion'));assert.ok(events.some(e=>e.type==='contact'));assert.ok(events.some(e=>e.type==='substep'&&e.stage==='before'));assert.ok(events.some(e=>e.type==='substep'&&e.stage==='after'));assert.ok(events.every((e,i)=>e.seq===i+1));for(const e of events.filter(e=>e.type==='motion'))assert.ok(Math.abs(e.timeEnd-e.timeStart-e.dt)<1e-12);
});
test('observer copies cannot mutate balls or actual geometry and throw always restores hook',()=>{
 const options={seconds:1,drain:.1,replaySeconds:1.1,replayFPS:30},plain=measurePinAdjustment(config(),options);const observed=withFlowTrace(()=>measurePinAdjustment(config(),options),pins(),e=>{if(e.part?.a)e.part.a.x=1e9;if(e.after)e.after.x=1e9;if(e.balls?.[0])e.balls[0].x=1e9;});assert.deepEqual(observed.result,plain);assert.equal(activePhysicsTrace,null);assert.throws(()=>withPhysicsTrace(()=>{throw Error('original');},()=>{}),/original/);assert.equal(activePhysicsTrace,null);assert.throws(()=>withPhysicsTrace(()=>withPhysicsTrace(()=>{},()=>{}),()=>{}),/Nested|nested/);assert.equal(activePhysicsTrace,null);
});
test('actual pin correction with false impulse and successful reflection are distinct, original pin ID retained',()=>{
 const p=new Physics();p.pins=[{id:77,x:100,y:100,r:.2,role:'michi'}];const away={id:1,x:101,y:100,r:1.8,vx:10,vy:0,hits:0,contactCount:0},toward={...away,id:2,vx:-10};const events=[];withPhysicsTrace(()=>{p.resolvePins(away);p.resolvePins(toward);},e=>events.push(e));assert.equal(events.length,2);assert.equal(events[0].solverResult,false);assert.equal(events[0].positionChanged,true);assert.equal(events[0].velocityChanged,false);assert.equal(events[0].part.id,77);assert.equal(events[1].solverResult,true);assert.equal(events[1].velocityChanged,true);
});
test('actual pair contacts contain both IDs and both correction snapshots, outcomes expose real terminal state',()=>{
 const model=createBoardFlow({lcd:true});const p=model.flow.physics;p.pins=[];p.colliders=[];p.mechanisms=[];p.pockets=[{id:4,kind:'start',x:208.5,y:553,w:20}];p.separateLaunchPlane=false;p.gate.active=false;p.rightChucker.scoop.active=false;p.rightChucker.cover.active=false;p.balls=[{id:1,x:150,y:400,r:1.8,vx:1,vy:0,age:0},{id:2,x:152,y:400,r:1.8,vx:-1,vy:0,age:0}];const events=[];withPhysicsTrace(()=>p.step(1/120,model.flow.game),e=>events.push(e));const pair=events.find(e=>e.type==='contact'&&e.part.kind==='ball-pair');assert.ok(pair);assert.equal(pair.before.id,1);assert.equal(pair.peerBefore.id,2);assert.notEqual(pair.before.x,pair.after.x);withPhysicsTrace(()=>p.recordOutcome(p.balls[0],'out'),e=>events.push(e));assert.equal(events.at(-1).outcome,'out');assert.equal(events.at(-1).ball.id,1);
});
test('finite road gap centre crossings distinguish direction, ordinary/large gap and radius clearance',()=>{
 const gaps=roadGapDefinitions(pins());assert.equal(gaps.length,25);assert.equal(gaps.filter(g=>g.classification==='ordinary').length,23);assert.deepEqual(gaps.filter(g=>g.classification==='large-break').map(g=>g.id),['10-11','22-23']);const g=gaps[0],x=(g.a.x+g.b.x)/2,y=(g.a.y+g.b.y)/2,before={id:1,x,y:y-2,r:1.8},after={...before,y:y+2};const hit=gapCrossings(before,after,[g]);assert.equal(hit.length,1);assert.equal(hit[0].direction,'descending');assert.equal(gapCrossings(after,before,[g])[0].direction,'ascending');assert.equal(gapCrossings({...before,x:g.a.x-10},{...after,x:g.a.x-10},[g]).length,0);assert.equal(gapCrossings(before,after,[{...g,a:{...g.a,x:x-.5},b:{...g.b,x:x+.5}}])[0].discClearAtCentreCross,false);
});
test('synthetic250 control retains every old measurement field and captures all actual outcome IDs',()=>{
 const plain=synthetic(()=>measureS8WindmillCase(config()));const traced=synthetic(()=>withFlowTrace(()=>measureS8WindmillCase(config()),pins()));assert.deepEqual(traced.result,plain);assert.equal(traced.result.physical.shots,250);assert.equal(traced.trace.balls.filter(b=>b.outcome?.kind==='out').length,250);assert.equal(traced.trace.counts.outcome,250);
});

test('gap motion/correction attribution keeps plane and pair summary uses the actual other ID',()=>{
 const events=[],collector=createFlowTraceCollector(pins(),e=>events.push(e)),g=roadGapDefinitions(pins())[0],x=(g.a.x+g.b.x)/2,y=(g.a.y+g.b.y)/2,before={id:1,x,y:y-2,r:1.8,vx:0,vy:1,front:true},after={...before,y:y+2};collector.accept({type:'motion',time:1,timeStart:.9,timeEnd:1,dt:.1,before,after});collector.accept({type:'contact',time:1,stage:'pair',part:{kind:'ball-pair',id:2},before:after,after:before,peerBefore:{...before,id:2},peerAfter:{...after,id:2},solverResult:true,velocityChanged:false,positionChanged:true});const crosses=events.filter(e=>e.type==='gap-cross');assert.ok(crosses.some(e=>e.sourceKind==='kinematic-motion'&&e.frontBefore&&e.frontAfter));assert.ok(crosses.some(e=>e.sourceKind==='solver-position-correction'));const rows=collector.summary().balls;assert.equal(rows.find(r=>r.ballId===1).lastChangedContact.otherBallId,2);assert.equal(rows.find(r=>r.ballId===2).lastChangedContact.otherBallId,1);
});
test('runner allows only explicit single unchanged baseline phase0 and full oracle compares every physical field',()=>{
 const args=['--out','out','--plan','plan','--manifest','manifest','--oracle','old.json.gz','--phase','0','--stage','preflight'];assert.equal(parseFlowTraceArgs(args)['--stage'],'preflight');assert.throws(()=>parseFlowTraceArgs([...args,'--case','other']),/Unknown/);assert.throws(()=>parseFlowTraceArgs(args.map(x=>x==='preflight'?'run':x)),/Frozen/);assert.throws(()=>parseFlowTraceArgs(args.map(x=>x==='0'?'.175':x)),/phase0/);const r={physical:{shots:250},events:[{ballId:1,time:0}],replayFrames:[{x:1}],sourceSHA:'new'};assert.equal(compareFlowOracle(r,{...r,sourceSHA:'old'}).allExistingMeasurementFieldsExact,true);assert.equal(compareFlowOracle(r,{...r,replayFrames:[{x:2}]}).allExistingMeasurementFieldsExact,false);for(const key of ['configSHA','layoutSHA','flowOptions'])assert.equal(compareFlowOracle({...r,[key]:'one'},{...r,[key]:'two'}).allExistingMeasurementFieldsExact,false);
});

test('solid polygon contact uses full solid bounds even when compatibility a/b span only another edge',()=>{
 const p=new Physics(),points=[{x:100,y:100},{x:120,y:100},{x:120,y:120},{x:100,y:120}],solid=prepareSolidPolygon(points);p.pins=[];p.mechanisms=[];p.gate.active=false;p.rightChucker.scoop.active=false;p.rightChucker.cover.active=false;p.colliders=[{shape:'solid-polygon',solid,a:points[0],b:points[3],r:0,role:'synthetic-solid',restitution:.1}];const ball={id:1,x:110,y:99,r:1.8,vx:0,vy:10,contactCount:0},events=[];withPhysicsTrace(()=>p.advanceBall(ball,0),e=>events.push(e));const c=events.find(e=>e.type==='contact');assert.ok(c);assert.equal(c.part.role,'synthetic-solid');assert.ok(c.positionChanged);assert.ok(ball.y<=98.2+1e-9);assert.ok(ball.vy<0);
});

test('saved gzip/JSON OFF oracle matches traced in-memory ON JSON exactly, including explicit configuration fields',()=>{
 const opts={seconds:.5,drain:.2,replaySeconds:.7,replayFPS:30},plain=measurePinAdjustment(config(),opts),old=JSON.parse(gunzipSync(gzipSync(JSON.stringify(plain)))),observed=withFlowTrace(()=>measurePinAdjustment(config(),opts),pins()).result;assert.equal(compareFlowOracle(observed,old).allExistingMeasurementFieldsExact,true);assert.equal(compareFlowOracle({...observed,notSaved:undefined},old).allExistingMeasurementFieldsExact,true);assert.equal(compareFlowOracle({...observed,extra:1},old).allExistingMeasurementFieldsExact,false);const proof=compareFlowOracle(observed,old);assert.equal(proof.newBodySHA,proof.historicalBodySHA);
});
